import os

# Read all relevant files
files = {}
for f in ['ledger.txt', 'lessons.txt', 'last_attempt_summary.txt']:
    path = os.path.join('.', f)
    if os.path.exists(path):
        with open(path, 'r') as fh:
            files[f] = fh.read()
    else:
        files[f] = "[FILE NOT FOUND]"

for name, content in files.items():
    print(f"===== {name} =====")
    print(content)
    print()

